('idf-combat', 'idf-combat-service', 'idf', true, 'verified', '2026-10-21', '{"id":"idf-combat","slug":"idf-combat-service","name":"שירות סדיר — מסלולי לחימה","pathway":"idf","typeLabel":"מסלול שירות בצה״ל","kind":"track","regions":["nationwide"],"locationLabel":"בכל הארץ, לפי שיבוץ","shortDescription":"גיוס ישיר לשירות סדיר עם עניין בתפקידי לחימה ושדה. כיוון שמתאים למי שמחפש אתגר פיזי ומנטלי ועבודת צוות, ישירות אחרי התיכון.","highlights":["גיוס ישיר אחרי י״ב","אתגר פיזי ועבודת צוות","אפשרות להמשך לפיקוד וקצונה"],"limitations":["השיבוץ בפועל נקבע על ידי צה״ל לפי דרישות רשמיות, כשירות רפואית, מבדקים, צרכי המערכת ותפקידים פנויים. ההמלצה כאן אינה מבטיחה שיבוץ בתפקיד כלשהו."],"attributes":{"torahIntensity":0,"militaryEmphasis":4,"militaryModel":"direct_service","torahServiceBalance":null,"religiousEnvironments":["religious_zionist","open_religious","mixed_backgrounds","general"],"development":["fitness","leadership","independence"],"serviceInterests":["combat","leadership_command"],"environmentStyles":["structure","challenge","teamwork"],"learningStyles":["experiential","practical"],"strengths":["military_prep","leadership"],"residential":"varies","duration":"multi_year","communitySize":"large","audience":"all"},"profile":{"overview":"שירות סדיר בצה״ל הוא המסלול הישיר אחרי התיכון. רשומה זו מתארת כיוון שירות כללי — תפקידי לחימה ושדה — ולא יחידה מסוימת.","militaryIntegration":"השיבוץ בפועל נקבע על ידי צה״ל לפי דרישות רשמיות, כשירות רפואית, מבדקים, צרכי המערכת ותפקידים פנויים. ההמלצה כאן אינה מבטיחה שיבוץ בתפקיד כלשהו.","faq":[{"q":"איפה אפשר לקבל מידע רשמי ועדכני?","a":"באתר צה״ל, במדור ״השירות שלי״, ובפנייה ישירה לגורמי הגיוס. המידע כאן כללי בלבד."}]},"website":"https://www.idf.il/השירות-שלי/","sources":[{"label":"אתר צה״ל — סוגי השירות בצה״ל","url":"https://www.idf.il/השירות-שלי/סוגי-השירות-בצה-ל/","kind":"official"},{"label":"אתר צה״ל — שירות סדיר","url":"https://www.idf.il/השירות-שלי/סוגי-השירות-בצה-ל/סדיר/","kind":"official"}],"lastVerified":"2026-10-21","verificationStatus":"verified","verificationNotes":"אומת שהמידע הכללי על סוגי השירות מופיע באתר הרשמי של צה״ל. אין כאן מידע על יחידות, תנאי קבלה או שיבוץ.","published":true}'::jsonb),
('idf-tech', 'idf-technology-intelligence', 'idf', true, 'verified', '2026-10-21', '{"id":"idf-tech","slug":"idf-technology-intelligence","name":"שירות סדיר — טכנולוגיה, מודיעין וסייבר","pathway":"idf","typeLabel":"מסלול שירות בצה״ל","kind":"track","regions":["nationwide"],"locationLabel":"בכל הארץ, לפי שיבוץ","shortDescription":"גיוס ישיר עם עניין בתחומי טכנולוגיה, מודיעין וסייבר. כיוון למי שנמשך לחשיבה אנליטית, לפתרון בעיות ולפיתוח מקצועי בזמן השירות.","highlights":["גיוס ישיר אחרי י״ב","עניין בטכנולוגיה וחשיבה אנליטית","פיתוח מיומנויות מקצועיות"],"limitations":["השיבוץ בפועל נקבע על ידי צה״ל לפי דרישות רשמיות, כשירות רפואית, מבדקים, צרכי המערכת ותפקידים פנויים. ההמלצה כאן אינה מבטיחה שיבוץ בתפקיד כלשהו."],"attributes":{"torahIntensity":0,"militaryEmphasis":3,"militaryModel":"direct_service","torahServiceBalance":null,"religiousEnvironments":["religious_zionist","open_religious","mixed_backgrounds","general"],"development":["professional","independence","clarity"],"serviceInterests":["tech_intel","professional_technical"],"environmentStyles":["structure","challenge","teamwork"],"learningStyles":["practical","intensive_study"],"strengths":["academic_professional"],"residential":"varies","duration":"multi_year","communitySize":"large","audience":"all"},"profile":{"overview":"כיוון שירות כללי בתחומי הטכנולוגיה, המודיעין והסייבר. אין כאן התחייבות לתפקיד או ליחידה — המיון והשיבוץ נעשים על ידי צה״ל.","militaryIntegration":"השיבוץ בפועל נקבע על ידי צה״ל לפי דרישות רשמיות, כשירות רפואית, מבדקים, צרכי המערכת ותפקידים פנויים. ההמלצה כאן אינה מבטיחה שיבוץ בתפקיד כלשהו.","faq":[{"q":"איפה אפשר לקבל מידע רשמי ועדכני?","a":"באתר צה״ל, במדור ״השירות שלי״, ובפנייה ישירה לגורמי הגיוס. המידע כאן כללי בלבד."}]},"website":"https://www.idf.il/השירות-שלי/","sources":[{"label":"אתר צה״ל — סוגי השירות בצה״ל","url":"https://www.idf.il/השירות-שלי/סוגי-השירות-בצה-ל/","kind":"official"},{"label":"אתר צה״ל — שירות סדיר","url":"https://www.idf.il/השירות-שלי/סוגי-השירות-בצה-ל/סדיר/","kind":"official"}],"lastVerified":"2026-10-21","verificationStatus":"verified","verificationNotes":"אומת שהמידע הכללי על סוגי השירות מופיע באתר הרשמי של צה״ל. אין כאן מידע על יחידות, תנאי קבלה או שיבוץ.","published":true}'::jsonb),
('idf-people', 'idf-education-community', 'idf', true, 'verified', '2026-10-21', '{"id":"idf-people","slug":"idf-education-community","name":"שירות סדיר — חינוך, אנשים וקהילה","pathway":"idf","typeLabel":"מסלול שירות בצה״ל","kind":"track","regions":["nationwide"],"locationLabel":"בכל הארץ, לפי שיבוץ","shortDescription":"גיוס ישיר עם עניין בתפקידים שעוסקים באנשים: הדרכה, חינוך, ליווי וקהילה. כיוון למי שרוצה להשפיע דרך עבודה עם אחרים.","highlights":["גיוס ישיר אחרי י״ב","עבודה עם אנשים","פיתוח מנהיגות ותקשורת"],"limitations":["השיבוץ בפועל נקבע על ידי צה״ל לפי דרישות רשמיות, כשירות רפואית, מבדקים, צרכי המערכת ותפקידים פנויים. ההמלצה כאן אינה מבטיחה שיבוץ בתפקיד כלשהו."],"attributes":{"torahIntensity":0,"militaryEmphasis":3,"militaryModel":"direct_service","torahServiceBalance":null,"religiousEnvironments":["religious_zionist","open_religious","mixed_backgrounds","general"],"development":["leadership","social","independence"],"serviceInterests":["education_community","other_meaningful","leadership_command"],"environmentStyles":["teamwork","structure","mentorship"],"learningStyles":["experiential","discussion"],"strengths":["leadership","community"],"residential":"varies","duration":"multi_year","communitySize":"large","audience":"all"},"profile":{"overview":"כיוון שירות כללי בתפקידים שבמרכזם עבודה עם אנשים — הדרכה, חינוך וקהילה. אין כאן התחייבות לתפקיד מסוים.","militaryIntegration":"השיבוץ בפועל נקבע על ידי צה״ל לפי דרישות רשמיות, כשירות רפואית, מבדקים, צרכי המערכת ותפקידים פנויים. ההמלצה כאן אינה מבטיחה שיבוץ בתפקיד כלשהו.","faq":[{"q":"איפה אפשר לקבל מידע רשמי ועדכני?","a":"באתר צה״ל, במדור ״השירות שלי״, ובפנייה ישירה לגורמי הגיוס. המידע כאן כללי בלבד."}]},"website":"https://www.idf.il/השירות-שלי/","sources":[{"label":"אתר צה״ל — סוגי השירות בצה״ל","url":"https://www.idf.il/השירות-שלי/סוגי-השירות-בצה-ל/","kind":"official"},{"label":"אתר צה״ל — שירות סדיר","url":"https://www.idf.il/השירות-שלי/סוגי-השירות-בצה-ל/סדיר/","kind":"official"}],"lastVerified":"2026-10-21","verificationStatus":"verified","verificationNotes":"אומת שהמידע הכללי על סוגי השירות מופיע באתר הרשמי של צה״ל. אין כאן מידע על יחידות, תנאי קבלה או שיבוץ.","published":true}'::jsonb),
('idf-midrasha-garin', 'midrasha-garin-track', 'idf', true, 'verified', '2026-10-21', '{"id":"idf-midrasha-garin","slug":"midrasha-garin-track","name":"מסלול גרעיני מדרשות","pathway":"idf","typeLabel":"מסלול שירות משולב לימוד תורה","kind":"track","regions":["nationwide"],"locationLabel":"מדרשות בכמה אזורים בארץ","shortDescription":"מסלול של משרד הביטחון לבנות דתיות שרוצות לשרת בצה״ל ולצד זה ללמוד תורה במדרשה, בגרעין עם ליווי של המדרשה לאורך השירות.","highlights":["שנת לימוד במדרשה לפני השירות","שירות בגרעין","ליווי של המדרשה לאורך השירות"],"limitations":["פרטי המסלול נקבעים מדי שנה בהנחיות האגף — יש לוודא את המידע העדכני.","השיבוץ בפועל נקבע על ידי צה״ל לפי דרישות רשמיות, כשירות רפואית, מבדקים, צרכי המערכת ותפקידים פנויים. ההמלצה כאן אינה מבטיחה שיבוץ בתפקיד כלשהו."],"attributes":{"torahIntensity":3,"militaryEmphasis":3,"militaryModel":"shiluv","torahServiceBalance":0.6,"religiousEnvironments":["religious_zionist","open_religious"],"development":["torah_growth","leadership","social","independence"],"serviceInterests":["education_community","tech_intel","other_meaningful"],"environmentStyles":["teamwork","mentorship"],"learningStyles":["intensive_study","discussion"],"strengths":["torah_quality","community","guidance","spiritual_atmosphere"],"residential":"residential","duration":"multi_year","communitySize":"medium","audience":"women"},"profile":{"overview":"לפי האגף הביטחוני־חברתי במשרד הביטחון, מסלול גרעיני המדרשות נועד לבנות דתיות שרוצות לשרת בצה״ל לצד לימוד תורה במדרשה. המשתתפות לומדות כשנה במדרשה ומתגייסות במסגרת גרעין.","programStructure":"לפי משרד הביטחון: הגיוס נעשה במסלול נח״ל ל־32 חודשים, מתוכם כ־8 חודשי לימוד במדרשה ו־24 חודשי שירות פעיל מלא. המדרשה ממשיכה ללוות את המשתתפות לאורך השירות.","militaryIntegration":"לפי משרד הביטחון, המשתתפות משובצות בתפקידים כמו מדריכות, מודיעין, חיל האוויר ועוד. השיבוץ בפועל נקבע על ידי צה״ל לפי דרישות רשמיות, כשירות רפואית, מבדקים, צרכי המערכת ותפקידים פנויים. ההמלצה כאן אינה מבטיחה שיבוץ בתפקיד כלשהו.","admissions":"לפי משרד הביטחון, ההרשמה נעשית דרך נציגות המדרשות עד 31 במרץ בכל שנה. המועדים עשויים להשתנות בהנחיות השנתיות.","faq":[{"q":"אילו מדרשות משתתפות?","a":"בעמוד משרד הביטחון מופיעות מדרשות לינדנבאום, עין הנצי״ב, באר, מגדל עוז ורוני. כדאי לבדוק את הרשימה העדכנית."}]},"website":"https://noar.mod.gov.il/Out%20to%20Israel/Pages/garen-Medrasa.aspx","sources":[{"label":"משרד הביטחון, האגף הביטחוני־חברתי — גרעיני מדרשות","url":"https://noar.mod.gov.il/Out%20to%20Israel/Pages/garen-Medrasa.aspx","kind":"government"}],"lastVerified":"2026-10-21","verificationStatus":"verified","verificationNotes":"כל הפרטים נלקחו מעמוד המסלול באתר משרד הביטחון.","published":true}'::jsonb),
('mechina-bnei-david', 'bnei-david-eli', 'mechina', true, 'partial', '2026-10-21', '{"id":"mechina-bnei-david","slug":"bnei-david-eli","name":"המכינה הקדם־צבאית בני דוד, עלי","pathway":"mechina","typeLabel":"מכינה קדם־צבאית דתית","kind":"institution","regions":["judea_samaria"],"locationLabel":"עלי, בנימין","shortDescription":"המכינה הקדם־צבאית הדתית הראשונה, שנוסדה ב־1988. מטרתה להכין צעירים מהציונות הדתית לשירות צבאי מלא ומשמעותי, עם דגש על לחימה ופיקוד.","highlights":["המכינה הדתית הראשונה (1988)","הכנה לשירות מלא","דגש על לחימה ופיקוד"],"limitations":["האתר הרשמי לא נבדק ישירות — הפרטים מבוססים על מקור אנציקלופדי.","משך התוכנית לא אומת."],"attributes":{"torahIntensity":3,"militaryEmphasis":4,"militaryModel":"pre_military","torahServiceBalance":null,"religiousEnvironments":["religious_zionist"],"development":["leadership","torah_growth","fitness","independence"],"serviceInterests":["combat","leadership_command"],"environmentStyles":["structure","challenge","mentorship"],"learningStyles":["intensive_study","discussion"],"strengths":["military_prep","leadership","torah_quality"],"residential":"residential","duration":"varies","communitySize":"unknown","audience":"men"},"profile":{"overview":"בני דוד בעלי נוסדה ב־1988 על ידי הרב אלי סדן והרב יגאל לוינשטיין, והיא נחשבת למכינה הקדם־צבאית הדתית הראשונה. המכינה פועלת בפיקוח משרד הביטחון.","philosophy":"מטרת המכינה היא להכין צעירים מהציונות הדתית לשירות צה״לי מלא ומשמעותי, בעיקר ביחידות קרביות ובתפקידי פיקוד וקצונה.","admissions":"לפי ״כל־זכות״, ההרשמה למכינות נעשית בדרך כלל במהלך כיתה י״ב (ספטמבר עד מרץ) דרך מערכת ההרשמה של מועצת המכינות, וכוללת לרוב ריאיון ומיון. אפשר להגיש מועמדות לכמה מכינות. תנאי הקבלה הספציפיים של המכינה הזו לא אומתו.","financial":"לפי ״כל־זכות״, ההשתתפות במכינות כרוכה בתשלום עבור הוצאות המחיה, ברוב המכינות בסך של כמה מאות שקלים בחודש, ולכל מכינה תוכניות מלגה וסיוע. הסכום המדויק במכינה הזו לא אומת — יש לברר ישירות.","faq":[]},"sources":[{"label":"Wikipedia — Bnei David Mechina","url":"https://en.wikipedia.org/wiki/Bnei_David_Mechina","kind":"encyclopedia"},{"label":"כל־זכות — מכינה קדם־צבאית","url":"https://www.kolzchut.org.il/he/מכינה_קדם_צבאית","kind":"directory"}],"lastVerified":"2026-10-21","verificationStatus":"partial","verificationNotes":"קיום המוסד, שנת הייסוד והמייסדים אומתו ממקור אנציקלופדי. האתר הרשמי ופרטי הקשר טרם אומתו ישירות.","published":true}'::jsonb),
('mechina-ein-prat', 'ein-prat-kfar-adumim', 'mechina', true, 'verified', '2026-10-21', '{"id":"mechina-ein-prat","slug":"ein-prat-kfar-adumim","name":"עין פרת — מכינה קדם־צבאית כפר אדומים","pathway":"mechina","typeLabel":"מכינה קדם־צבאית מעורבת","kind":"institution","regions":["judea_samaria","jerusalem"],"locationLabel":"כפר אדומים, הרי יהודה","shortDescription":"מכינה לבוגרי י״ב מרקע דתי, חילוני ומסורתי, שמשלבת לימוד יהודי, ציוני ופילוסופי עם התנדבות, טיולים והכנה לשירות.","highlights":["קבוצה מעורבת: דתיים, חילונים ומסורתיים","יותר מ־1,000 שעות לימוד בשנה","חיים עצמאיים בבתים משותפים"],"limitations":["לא ציינו במקור למי מיועדת המכינה מבחינת מגדר — כדאי לברר."],"attributes":{"torahIntensity":2,"militaryEmphasis":2,"militaryModel":"pre_military","torahServiceBalance":null,"religiousEnvironments":["mixed_backgrounds","open_religious","general"],"development":["leadership","independence","clarity","social"],"serviceInterests":["leadership_command","education_community","other_meaningful"],"environmentStyles":["freedom","teamwork","challenge"],"learningStyles":["discussion","experiential"],"strengths":["leadership","community","spiritual_atmosphere"],"residential":"residential","duration":"one_year","communitySize":"unknown","audience":"unknown"},"profile":{"overview":"עין פרת – האקדמיה למנהיגות מפעילה מכינה קדם־צבאית בכפר אדומים לבוגרי י״ב מרקע דתי, חילוני ומסורתי. התוכנית שנתית וכוללת יותר מ־1,000 שעות לימוד בשנה.","philosophy":"לפי אתר עין פרת, הלימוד משלב תכנים יהודיים, ציוניים ופילוסופיים עם התנדבות, עבודה קהילתית וטיולים, ומדגיש זהות יהודית־ציונית, מנהיגות ערכית ואחריות לחברה.","programStructure":"תוכנית שנתית. ההכנה לשירות כוללת מוכנות פיזית ומנטלית.","livingArrangements":"לפי האתר, החניכים גרים בבתים משותפים ומנהלים בעצמם חלק גדול מהחיים היומיומיים.","admissions":"לפי ״כל־זכות״, ההרשמה למכינות נעשית בדרך כלל במהלך כיתה י״ב (ספטמבר עד מרץ) דרך מערכת ההרשמה של מועצת המכינות, וכוללת לרוב ריאיון ומיון. אפשר להגיש מועמדות לכמה מכינות. תנאי הקבלה הספציפיים של המכינה הזו לא אומתו.","financial":"לפי ״כל־זכות״, ההשתתפות במכינות כרוכה בתשלום עבור הוצאות המחיה, ברוב המכינות בסך של כמה מאות שקלים בחודש, ולכל מכינה תוכניות מלגה וסיוע. הסכום המדויק במכינה הזו לא אומת — יש לברר ישירות.","faq":[{"q":"האם יש לעין פרת מכינות נוספות?","a":"כן. לפי האתר יש תוכניות נוספות, למשל בנופי פרת, בקיבוץ סופה ובקיבוץ ניר עם. כדאי לבדוק באתר את המיקומים העדכניים."}]},"website":"https://ein-prat.com/","contact":{"phone":["02-5905992","02-5905993"],"address":"מכינת עין פרת, כפר אדומים 9061800"},"sources":[{"label":"עין פרת — תוכניות קדם־צבאיות (אתר רשמי)","url":"https://ein-prat.com/academy-for-leadership-pre-military-programs/?lang=en","kind":"official"},{"label":"כל־זכות — מכינה קדם־צבאית","url":"https://www.kolzchut.org.il/he/מכינה_קדם_צבאית","kind":"directory"}],"lastVerified":"2026-10-21","verificationStatus":"verified","verificationNotes":"התיאור, הכתובת והטלפון נלקחו מהאתר הרשמי. עלויות ותנאי קבלה ספציפיים לא אומתו.","published":true}'::jsonb),
