('hesder-hakotel', 'hakotel', 'hesder', true, 'verified', '2026-10-21', '{"id":"hesder-hakotel","slug":"hakotel","name":"ישיבת הכותל","pathway":"hesder","typeLabel":"ישיבת הסדר","kind":"institution","regions":["jerusalem"],"locationLabel":"העיר העתיקה, ירושלים","shortDescription":"ישיבת הסדר בעיר העתיקה בירושלים, מול הכותל, שנוסדה ב־1967. עיקר סדר היום מוקדש ללימוד גמרא, והתלמידים גרים בפנימייה בקמפוס.","highlights":["בלב העיר העתיקה","עיקר הלימוד בגמרא","פנימייה בקמפוס מאובטח"],"limitations":[],"attributes":{"torahIntensity":4,"militaryEmphasis":2,"militaryModel":"hesder","torahServiceBalance":0.3,"religiousEnvironments":["religious_zionist"],"development":["torah_growth","independence"],"serviceInterests":["combat","leadership_command"],"environmentStyles":["structure","mentorship"],"learningStyles":["intensive_study"],"strengths":["torah_quality","spiritual_atmosphere","location"],"residential":"residential","duration":"multi_year","communitySize":"unknown","audience":"men"},"profile":{"overview":"ישיבת הכותל נוסדה ב־1967, זמן קצר אחרי מלחמת ששת הימים, בעיר העתיקה בירושלים מול הכותל המערבי.","programStructure":"לפי אתר הישיבה, עיקר סדר היום מוקדש לגמרא, והשיעורים ניתנים בשלוש נקודות במהלך היום. התלמידים הישראלים לומדים לפחות חמש שנים, מתוכן לפחות 3.5 שנות לימוד ולפחות 1.5 שנות שירות צבאי.","militaryIntegration":"לפי משרד הביטחון, ישיבות ההסדר משלבות לימודים תורניים לצד שירות צבאי מקוצר במסגרת דתית. במסלול ההסדר הקלאסי מדובר ב־44 חודשי שירות (כולל תקופות של״ת), מתוכם כ־17 חודשי שירות פעיל. קיימים גם מסלולים נוספים (כמו ״שש־הסדר״ ו״שילובים״) — יש לברר באיזה מסלול פועלת הישיבה.","livingArrangements":"לפי האתר, התלמידים גרים בפנימיית הישיבה, ובכל דירה יש מטבחון עם מקרר. הקמפוס סגור ומאובטח, והכניסה בכרטיס או במפתח.","faq":[]},"website":"https://hakotel.org.il/","contact":{"phone":["02-628-8175"],"address":"רח׳ המקובלים 7, העיר העתיקה, ירושלים"},"sources":[{"label":"ישיבת הכותל — שאלות נפוצות (אתר רשמי)","url":"https://hakotel.org.il/english/student-life/faq/","kind":"official"},{"label":"Wikipedia — Yeshivat HaKotel","url":"https://en.wikipedia.org/wiki/Yeshivat_HaKotel","kind":"encyclopedia"},{"label":"משרד הביטחון, האגף הביטחוני־חברתי — מסלול ישיבות ההסדר","url":"https://noar.mod.gov.il/Haredim/Pages/מסלול-ישיבות-ההסדר.aspx","kind":"government"}],"lastVerified":"2026-10-21","verificationStatus":"verified","verificationNotes":"מבנה הלימוד, המגורים ופרטי הקשר נלקחו מהאתר הרשמי. עלויות ותנאי קבלה לא אומתו.","published":true}'::jsonb),
