('yeshiva-mercaz-harav', 'mercaz-harav', 'yeshiva', true, 'verified', '2026-10-21', '{"id":"yeshiva-mercaz-harav","slug":"mercaz-harav","name":"ישיבת מרכז הרב","pathway":"yeshiva","typeLabel":"ישיבה גבוהה","kind":"institution","regions":["jerusalem"],"locationLabel":"קריית משה, ירושלים","shortDescription":"ישיבה שייסד הרב אברהם יצחק הכהן קוק ב־1924 בירושלים, ומהבולטות בישיבות הציונות הדתית. בראשה עומד הרב יעקב שפירא.","highlights":["נוסדה על ידי הרב קוק (1924)","שיעורי גמרא, הלכה ואמונה","כולל לבוגרים"],"limitations":["המסלול הצבאי בישיבה לא אומת — יש לברר ישירות."],"attributes":{"torahIntensity":4,"militaryEmphasis":0,"militaryModel":"unknown","torahServiceBalance":null,"religiousEnvironments":["religious_zionist"],"development":["torah_growth"],"serviceInterests":[],"environmentStyles":["structure","mentorship"],"learningStyles":["intensive_study"],"strengths":["torah_quality","spiritual_atmosphere","alumni"],"residential":"residential","duration":"multi_year","communitySize":"large","audience":"men"},"profile":{"overview":"ישיבת מרכז הרב נוסדה ב־1924 על ידי הרב אברהם יצחק הכהן קוק, ונמצאת בשכונת קריית משה בירושלים. מאז 2007 עומד בראשה הרב יעקב שפירא.","philosophy":"לפי אתר הישיבה, מטרתה לקדש את שם ה׳, התורה, עם ישראל וארץ ישראל. באתר מופיעים שיעורים בגמרא, הלכה, אמונה ופרשת השבוע.","faq":[]},"website":"https://mercazharav.org.il/en/front-page/","contact":{"phone":["02-6524793"]},"sources":[{"label":"ישיבת מרכז הרב (אתר רשמי)","url":"https://mercazharav.org.il/en/front-page/","kind":"official"},{"label":"Wikipedia — Mercaz HaRav","url":"https://en.wikipedia.org/wiki/Mercaz_HaRav","kind":"encyclopedia"}],"lastVerified":"2026-10-21","verificationStatus":"verified","verificationNotes":"הטלפון והתיאור הכללי נלקחו מהאתר הרשמי. מסלולי שירות, קבלה ועלויות לא אומתו.","published":true}'::jsonb),
('yeshiva-har-hamor', 'har-hamor', 'yeshiva', true, 'verified', '2026-10-21', '{"id":"yeshiva-har-hamor","slug":"har-hamor","name":"ישיבת הר המור","pathway":"yeshiva","typeLabel":"ישיבה גבוהה","kind":"institution","regions":["jerusalem"],"locationLabel":"חומת שמואל (הר חומה), ירושלים","shortDescription":"ישיבה בירושלים שנוסדה ב־1998, עם לימוד גמרא שיטתי לפי מסכתות ולימוד יומי בכתבי הרב קוק. השירות הצבאי מתואם לכל תלמיד באופן אישי.","highlights":["לימוד גמרא לפי מסכת בכל זמן","לימוד אמונה יומי בכתבי הרב קוק","שירות צבאי שמתואם אישית"],"limitations":["פרטי הקשר לא מופיעים בעמוד שנבדק — יש לפנות דרך עמוד צור הקשר באתר."],"attributes":{"torahIntensity":4,"militaryEmphasis":1,"militaryModel":"individual","torahServiceBalance":0.2,"religiousEnvironments":["religious_zionist"],"development":["torah_growth"],"serviceInterests":[],"environmentStyles":["structure","mentorship"],"learningStyles":["intensive_study"],"strengths":["torah_quality","spiritual_atmosphere"],"residential":"residential","duration":"multi_year","communitySize":"large","audience":"men"},"profile":{"overview":"ישיבת הר המור נוסדה ב־1998 בירושלים, ובית המדרש הקבוע שלה נמצא בשכונת חומת שמואל (הר חומה). לפי אתר הישיבה לומדים בה כ־800 תלמידים, כמחציתם אברכים.","programStructure":"לפי האתר, התלמידים לומדים את המסכתות המרכזיות בתלמוד הבבלי במחזור קבוע, מסכת אחת בכל זמן, לצד הלכה, דיינות וחזרות. בכל יום יש זמן קבוע ללימוד אמונה בכתבי הרב קוק.","militaryIntegration":"לפי האתר, התלמידים משרתים בצה״ל במהלך שנותיהם בישיבה, והשירות של כל תלמיד מתואם לפי מה שמתאים לו, בהתייעצות עם רבותיו.","faq":[]},"website":"https://en.harhamor.co.il/about","sources":[{"label":"ישיבת הר המור — הלימודים בישיבה (אתר רשמי)","url":"https://en.harhamor.co.il/about","kind":"official"}],"lastVerified":"2026-10-21","verificationStatus":"verified","verificationNotes":"התיאור נלקח מהאתר הרשמי. פרטי קשר, עלויות ותנאי קבלה לא אומתו.","published":true}'::jsonb),
('yeshiva-beit-el', 'beit-el', 'yeshiva', true, 'partial', '2026-10-21', '{"id":"yeshiva-beit-el","slug":"beit-el","name":"ישיבת בית אל","pathway":"yeshiva","typeLabel":"ישיבה גבוהה","kind":"institution","regions":["judea_samaria"],"locationLabel":"בית אל, בנימין","shortDescription":"ישיבה שהקימו ב־1977 תלמידי ישיבת מרכז הרב, ובראשה עומד הרב זלמן ברוך מלמד. סביב הישיבה פועלים מוסדות נוספים, בהם מכינה קדם־צבאית.","highlights":["נוסדה ב־1977 על ידי תלמידי מרכז הרב","בראשה הרב זלמן ברוך מלמד","מרכז מוסדות שכולל גם מכינה"],"limitations":["האתר הרשמי ופרטי הקשר לא נבדקו ישירות.","המסלול הצבאי לא אומת."],"attributes":{"torahIntensity":4,"militaryEmphasis":0,"militaryModel":"unknown","torahServiceBalance":null,"religiousEnvironments":["religious_zionist"],"development":["torah_growth"],"serviceInterests":[],"environmentStyles":["structure","mentorship"],"learningStyles":["intensive_study"],"strengths":["torah_quality","spiritual_atmosphere"],"residential":"residential","duration":"multi_year","communitySize":"medium","audience":"men"},"profile":{"overview":"ישיבת בית אל הוקמה בסוף 1977 על ידי תלמידי ישיבת מרכז הרב, ובראשה עומד הרב זלמן ברוך מלמד. מרכז המוסדות כולל גם ישיבה תיכונית, אולפנות ומכינה קדם־צבאית.","faq":[]},"sources":[{"label":"Wikipedia — Beit El yeshiva","url":"https://en.wikipedia.org/wiki/Beit_El_yeshiva","kind":"encyclopedia"}],"lastVerified":"2026-10-21","verificationStatus":"partial","verificationNotes":"הפרטים אומתו ממקור אנציקלופדי. האתר הרשמי ופרטי הקשר טרם אומתו ישירות.","published":true}'::jsonb),
('idf-service-year', 'service-year', 'idf', true, 'partial', '2026-10-22', '{"id":"idf-service-year","slug":"service-year","name":"שנת שירות לפני הגיוס","pathway":"idf","typeLabel":"שנת התנדבות לפני השירות","kind":"track","regions":["nationwide"],"locationLabel":"במסגרות שונות ברחבי הארץ","shortDescription":"שנה של התנדבות למען הקהילה אחרי י״ב, שדוחה את הגיוס בשנה — לא מחליפה אותו. המתנדבים גרים לרוב בקומונות.","highlights":["התנדבות בקהילה לפני הגיוס","דוחה את הגיוס בשנה אחת"],"limitations":["שנת השירות לא מחליפה את הגיוס — היא דוחה אותו בשנה. התנאים הספציפיים של כל מסגרת לא אומתו כאן."],"attributes":{"torahIntensity":0,"militaryEmphasis":1,"militaryModel":"direct_service","torahServiceBalance":null,"religiousEnvironments":["religious_zionist","open_religious","mixed_backgrounds","general"],"development":["independence","social"],"serviceInterests":["education_community"],"environmentStyles":["teamwork"],"learningStyles":["experiential"],"strengths":["community"],"residential":"varies","duration":"one_year","communitySize":"varies","audience":"all"},"profile":{"overview":"לפי ״כל־זכות״, בוגרות ובוגרי י״ב יכולים לדחות את גיוסם בשנה ולהתנדב למען הקהילה — בפנימיות, בכפרי נוער, בבתי ספר שדה, בתנועות נוער, בשכונות ובמועדוניות. המתנדבים מתגוררים בקומונות ביישובים שונים, ומתחייבים לשירות צבאי או לאומי בתום השנה.","militaryIntegration":"שנת השירות ״איננה מחליפה את הגיוס, אלא דוחה אותו בשנה״ (כל־זכות).","admissions":"לפי ״כל־זכות״, נרשמים במהלך י״ב, בדרך כלל עד פברואר, ישירות למסגרת שבוחרים, ועוברים מיון. אחר כך חותמים על טופס דחיית שירות שנשלח במועד שקובע משרד הביטחון.","faq":[]},"sources":[{"label":"כל־זכות — התנדבות לשנת שירות","url":"https://www.kolzchut.org.il/he/התנדבות_לשנת_שירות","kind":"directory"}],"lastVerified":"2026-10-22","verificationStatus":"partial","verificationNotes":"המידע הכללי על שנת שירות מבוסס על ״כל־זכות״. אין כאן מידע על מסגרות ספציפיות, ומי מממן את השנה לא צוין במקור.","published":true}'::jsonb),
